1	import { describe, test, expect } from 'vitest';
2	import { ZimmSlideIndicator } from './zimmSlideIndicator.css';
3	
4	/**
5	 * `index.test.tsx` mocks `useMultiStyleConfig` globally, so this recipe's own object shape —
6	 * in particular the two colour tokens, which were carried as unconfirmed placeholders from
7	 * Step 1 until now — is never exercised by any shipped component test. Confirmed against Figma
8	 * via `get_design_context` on three separate variants (40002536:7956, :7947, :7954) — see this
9	 * file's own docblock for the full verification.
10	 */
11	describe('ZimmSlideIndicator — recipe wiring', () => {
12	  test('every declared part is produced by baseStyle', () => {
13	    const parts = Object.keys(ZimmSlideIndicator.baseStyle({}));
14	    expect(parts.sort()).toEqual([...ZimmSlideIndicator.parts].sort());
15	  });
16	
17	  test('active segment uses border-focus, not the previously-wired (visually-identical but semantically wrong) bg-05', () => {
18	    const { dot } = ZimmSlideIndicator.baseStyle({ isActive: true });
19	    expect(dot.background).toBe('var(--zimm-color-border-focus)');
20	  });
21	
22	  test('inactive segment uses border-secondary, not the previously-wired (visually different) opacity-40', () => {
23	    const { dot } = ZimmSlideIndicator.baseStyle({ isActive: false });
24	    expect(dot.background).toBe('var(--zimm-color-border-secondary)');
25	  });
26	
27	  test('segments are equal-width with no inter-segment gap, matching the real Figma component exactly', () => {
28	    const { root, dot } = ZimmSlideIndicator.baseStyle({});
29	    expect(root.gap).toBe(0);
30	    expect(dot.flex).toBe('1 0 0');
31	  });
32	});
